def factorize(n):
    factors = []
    # Start with the smallest prime factor
    divisor = 2
    while n >= divisor * divisor:
        while n % divisor == 0:
            factors.append(divisor)
            n //= divisor
        divisor += 1
    if n > 1:
        factors.append(n)
    return factors

def generate_partitions(factors):
    def backtrack(start, path, current_product):
        if current_product == 1:
            partitions.append(path[:])
        for i in range(start, len(factors)):
            if current_product * factors[i] > 1:
                path.append(factors[i])
                backtrack(i, path, current_product * factors[i])
                path.pop()

    partitions = []
    backtrack(0, [], 1)
    return partitions

