    return bin(number).count(bit)

def calculate_sides_strength(numbers):
    odd_strength = sum(count_bits(num, '1') for num in numbers if num % 2 != 0)
    even_strength = sum(count_bits(num, '0') for num in numbers if num % 2 == 0)
    return odd_strength, even_strength

